//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
scwin.MSG_CND_DTE_REQ = "검색조건 중 청구서제출일이 입력되지 않아 조회할 수 없습니다.";
scwin.MSG_CND_DTE_BIG = "검색조건 중 청구서제출 시작일이, 종료일 이후이므로 조회할 수 없습니다.";
scwin.NO_EXCEL_DATA = "해당데이터가 없습니다. 조회후 다운받으십시요.";
scwin.fn_GetPar;
scwin.glb_MenuId;
scwin.vScrenID = "ULDSTF05008.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_validate = function() {
    if ((edt_SDate.getValue() == "") || (edt_EDate.getValue() == "")) {
        $c.win.alert(scwin.MSG_CND_DTE_REQ);
        return;
    }
    if (edt_SDate.getValue() > edt_EDate.getValue()) {
        $c.win.alert(scwin.MSG_CND_DTE_BIG);
        return;
    }
    return true;
};
scwin.fn_list_sync = function() {
    if (!scwin.fn_validate()) {
        return;
    }
    var url = "/prelistingKosdaq.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listPrelisting&inputMessageId=PRELISTING_KOSDAQ_IN&outputMessageId=PRELISTING_KOSDAQ_OUT" + "&CLM_PLANDOC_SUBMIT_DD_BG=" + edt_SDate.getValue() + "&CLM_PLANDOC_SUBMIT_DD_ED=" + edt_EDate.getValue() + "&ISUR_CD=" + txb_IsurCd.getValue();
    dts_listPrelisting.DataID = encodeURI(url);
    dts_listPrelisting.reset();
    $c.cm.ShowWin(grd_Prelisting);
};
scwin.fn_proc_check_sync = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=PRELISTING_KOSDAQ_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.prelistingkosdaq.select.proclog.check.condition";
    dts_Proc_Check.DataID = encodeURI(url);
    dts_Proc_Check.reset();
    var vCtnt = "";
    if (dts_Proc_Check.getTotalRow() > 0) {
        for (var i = 1; i <= dts_Proc_Check.getTotalRow(); i++) {
            vCtnt += "\r\n";
            var vNm = "";
            if (dts_Proc_Check.getCellData(i, "EXAMPRN_NM") == "") {
                vNm += "심사자";
            }
            if (dts_Proc_Check.getCellData(i, "ACPT_COMPLT") == "" || dts_Proc_Check.getCellData(i, "ACPT_COMPLT") == "N") {
                if (vNm == "") {
                    vNm += "접수자";
                } else {
                    vNm += ",접수자";
                }
            }
            if (dts_Proc_Check.getCellData(i, "REVW_COMPLT") == "" || dts_Proc_Check.getCellData(i, "REVW_COMPLT") == "N") {
                if (vNm == "") {
                    vNm += "검토자";
                } else {
                    vNm += ",검토자";
                }
            }
            if (dts_Proc_Check.getCellData(i, "COMITE_COMPLT") == "") {
                if (vNm == "") {
                    vNm += "위원회완료자";
                } else {
                    vNm += ",위원회완료자";
                }
            }
            vCtnt += "상장완료후 " + dts_Proc_Check.getCellData(i, "COM_NM") + "가 " + vNm + "가 입력이 누락되었습니다, 입력해 주시기 바랍니다.";
            vCtnt += "\r\n";
        }
        $c.win.alert(vCtnt);
    }
};



// 발행기관목록
scwin.fn_GetParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션, 발행기관 목록팝업
    arrPar[0] = txb_IsurCd; // 코드값을 포함할 컨트롤
    arrPar[1] = txb_CoNm; // 명칭값을 포함할 컨트롤
    arrPar[2] = "KSQ_EXEM"; // 코스닥예비심사

    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParIsur = function(arrPar) {
    txb_IsurCd.setValue((arrPar.length >= 1 ? arrPar[0] : ""));
    txb_CoNm.setValue((arrPar.length >= 2 ? arrPar[1] : ""));
};

// 상세화면
scwin.fn_GetParDtl = function(arrPar) {
    // 상세화면열기
    var cRow = dts_listPrelisting.getRowPosition();
    arrPar[0] = dts_listPrelisting.getCellData(cRow, "ISUR_CD");
    arrPar[1] = dts_listPrelisting.getCellData(cRow, "BZ_PROCS_NO");
    arrPar[2] = dts_listPrelisting.getCellData(cRow, "COM_NM");
};
scwin.fn_SetParDtl = function(arrPar) {
    scwin.fn_list_sync();
};
scwin.fn_OpenDtl = async function(row) {
    if ((row <= dts_listPrelisting.getTotalRow()) && (dts_listPrelisting.getTotalRow() > 0)) {
        scwin.fn_GetPar = fn_GetParDtl;
        fn_SetPar = fn_SetParDtl;

        //frame.CreateFrame("DLG_PRECOM_DTL","../lstproc/ULDSTF05004.gfm", "예비심사청구상세", 10, 10, 1055 + 5, 670 + 30, "window", 0, 0, false);
        if ($c.frame.path("/top") != undefined) {
            $c.frame.path("/top").WinOpen("DLG_PRECOM_DTL", "../lstproc/ULDSTF05004.gfm?" + frame.FrameID, "예비심사청구상세", 1055 + 5, 700 + 30);
        } else {
            await $c.frame.CreateFrame("DLG_PRECOM_DTL", "../lstproc/ULDSTF05004.gfm", "예비심사청구상세", 10, 10, 1055 + 5, 700 + 30, "window", 0, 0, false);
        }
    }
};
scwin.fn_OpenInvRst = async function(row) {
    if ((row <= dts_listPrelisting.getTotalRow()) && (dts_listPrelisting.getTotalRow() > 0)) {
        scwin.fn_GetPar = fn_GetParDtl;
        fn_SetPar = undefined;
        await $c.frame.CreateDialogFrame("DLG_PRECOM_DTL", "../lstproc/ULDSTF05010.gfm", "위원회결과", 10, 10, 545 + 5, 600 + 30, "window");
    }
};
scwin.fn_OpenPubofr = async function(row) {
    if ((row <= dts_listPrelisting.getTotalRow()) && (dts_listPrelisting.getTotalRow() > 0)) {
        scwin.fn_GetPar = fn_GetParDtl;
        fn_SetPar = undefined;
        if ($c.frame.path("/top") != undefined) {
            $c.frame.path("/top").WinOpen("DLG_PRECOM_DTL", "../lstproc/ULDSTF05009.gfm?" + frame.FrameID, "공모", 795 + 5, 660 + 30);
        } else {
            await $c.frame.CreateFrame("DLG_PRECOM_DTL", "../lstproc/ULDSTF05009.gfm", "공모", 10, 10, 795 + 5, 660 + 30, "window", 0, 0, false);
        }
    }
};
scwin.grd_Prelisting_OnDblClick = function(row, colid) {
    scwin.fn_OpenDtl(row);
};
scwin.img_OpenDtl_onclick = function() {
    scwin.fn_OpenDtl(dts_listPrelisting.getRowPosition());
};
scwin.img_OpenInvRst_onclick = function() {
    scwin.fn_OpenInvRst(dts_listPrelisting.getRowPosition());
};
scwin.img_OpenPubofr_onclick = function() {
    scwin.fn_OpenPubofr(dts_listPrelisting.getRowPosition());
};
scwin.dts_listPrelisting_OnLoadCompleted = function(rowcount) {
    if (dts_listPrelisting.errorMsg) {
        $c.win.alert(dts_listPrelisting.errorMsg);
    } else {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    }
    $c.cm.CloseWin(rowcount, grd_Prelisting);
    scwin.fn_proc_check_sync();
};
scwin.dts_listPrelisting_OnLoadError = function() {
    $c.stf.alert_error(dts_listPrelisting);
};
scwin.dts_Proc_Check_OnLoadError = function() {
    $c.stf.alert_error(dts_Proc_Check);
};
scwin.img_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.btn_IsuCdSearch_onclick = function() {
    scwin.fn_GetPar = fn_GetParIsur;
    fn_SetPar = fn_SetParIsur;
    $c.lc.fn_PopFindIsurCdCorp();
};
scwin.img_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.img_Excel_onclick = function() {
    if (dts_listPrelisting.getTotalRow() > 0) {
        //엑셀 로그 
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_Prelisting, "예비심사리스트", "", "3");
    } else {
        $c.win.alert(scwin.NO_EXCEL_DATA);
    }
};
scwin.btn_SDate_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.btn_EDate_onclick = function() {
    popUpCalendar2(edt_EDate);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_SDate, edt_EDate);
};
scwin.txb_IsurCd_onblur = function() {
    if (txb_IsurCd.getValue() == "") {
        txb_CoNm.setValue("");
    }
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(pan_Cnd);
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    //edt_SDate.text = cGetMinusDate2(vCurDate, 365);
    edt_SDate.setValue("19000101");
    edt_EDate.setValue(vCurDate);
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
    scwin.fn_list_sync();
    /*
    glb_MenuId = InfoMenuID();
    alert( "menud id:"  + glb_MenuId + "\n" +
    	   "js_id:"	    + js_id + "\n"+
    	   "js_emp_no:" + js_emp_no + "\n"+
    	   "js_pass:"	+ js_pass + "\n"+
    	   "js_emp_nm:" + js_emp_nm + "\n"+
    	   "js_dep_cd:" + js_dep_cd + "\n"+
    	   "js_market:" + js_market
    	 );
    */

};
